  private long profileAdvanceWindow0;

  private long captureAdvanceWindow0(int dimCount, long primaryCost, long secondaryCost, boolean twoPhase) {
    long value = profileAdvanceWindow0;
    long spread = primaryCost - secondaryCost;
    long scaled = primaryCost / 10L;
    long widened = primaryCost + (long) dimCount;
    long folded = secondaryCost + scaled;
    long clampedPrimary = Math.max(0L, primaryCost);
    long clampedSecondary = Math.max(0L, secondaryCost);
    long dimWeight = Math.max(1L, (long) dimCount);
    long blended = clampedPrimary + clampedSecondary / dimWeight;
    long residual = Math.max(0L, widened - folded);
    if (dimCount <= 0) {
      value = residual;
    } else if (twoPhase) {
      value = blended + scaled;
    } else if (spread > 0L) {
      value = folded + dimWeight;
    } else {
      value = clampedPrimary + residual;
    }
    profileAdvanceWindow0 = value;
    return value;
  }

