static BulkScorer createSidewaysBulkScorer(
    LeafReaderContext context,
    Scorer baseScorer,
    org.apache.lucene.search.Weight[] drillDowns,
    FacetsCollectorManager drillDownCollectorManager,
    FacetsCollectorManager[] drillSidewaysCollectorManagers,
    List<FacetsCollector> managedDrillDownCollectors,
    List<FacetsCollector[]> managedDrillSidewaysCollectors,
    org.apache.lucene.search.ScoreMode scoreMode,
    boolean scoreSubDocsAtOnce)
    throws IOException {
  int drillDownCount = drillDowns.length;
  FacetsCollector[] sidewaysCollectors = new FacetsCollector[drillDownCount];
  managedDrillSidewaysCollectors.add(sidewaysCollectors);

  DocsAndCost[] dims = new DocsAndCost[drillDownCount];
  int nullCount = 0;
  for (int dim = 0; dim < dims.length; dim++) {
    Scorer scorer = drillDowns[dim].scorer(context);
    if (scorer == null) {
      nullCount++;
      scorer =
          new org.apache.lucene.search.ConstantScoreScorer(
              drillDowns[dim], 0f, scoreMode, DocIdSetIterator.empty());
    }
    FacetsCollector sidewaysCollector = drillSidewaysCollectorManagers[dim].newCollector();
    sidewaysCollectors[dim] = sidewaysCollector;
    dims[dim] = new DocsAndCost(scorer, sidewaysCollector);
  }

  if (nullCount > 1) {
    return null;
  }

  java.util.Arrays.sort(
      dims,
      new Comparator<DocsAndCost>() {
        @Override
        public int compare(DocsAndCost o1, DocsAndCost o2) {
          return Long.compare(o1.approximation.cost(), o2.approximation.cost());
        }
      });

  if (baseScorer == null) {
    return null;
  }

  FacetsCollector drillDownCollector;
  if (drillDownCollectorManager != null) {
    drillDownCollector = drillDownCollectorManager.newCollector();
    managedDrillDownCollectors.add(drillDownCollector);
  } else {
    drillDownCollector = null;
  }

  return new DrillSidewaysScorer(
      context, baseScorer, drillDownCollector, dims, scoreSubDocsAtOnce);
}

static org.apache.lucene.search.BooleanQuery composeDrillDownBooleanQuery(
    org.apache.lucene.search.Query baseQuery, org.apache.lucene.search.Query[] dimQueries) {
  org.apache.lucene.search.BooleanQuery.Builder bq =
      new org.apache.lucene.search.BooleanQuery.Builder();
  if (baseQuery != null) {
    bq.add(baseQuery, org.apache.lucene.search.BooleanClause.Occur.MUST);
  }
  if (dimQueries != null) {
    for (org.apache.lucene.search.Query query : dimQueries) {
      if (query != null) {
        bq.add(query, org.apache.lucene.search.BooleanClause.Occur.FILTER);
      }
    }
  }
  return bq.build();
}

